SELECT COUNT(*) AS review_rows, COUNT(DISTINCT order_id) AS reviewed_orders, COUNT(DISTINCT oi.product_id) AS reviewed_products
FROM order_reviews r
JOIN order_items oi ON r.order_id = oi.order_id;

WITH item_counts AS (
 SELECT order_id, COUNT(*) AS n_items FROM order_items GROUP BY 1
), paid AS (
 SELECT order_id, SUM(payment_value) amount FROM order_payments GROUP BY 1
)
SELECT o.order_status, COUNT(*) AS multi_item_orders, ROUND(AVG(p.amount),2) avg_payment
FROM orders o JOIN item_counts i USING(order_id) JOIN paid p USING(order_id)
WHERE o.order_purchase_timestamp >= TIMESTAMP '2017-01-01' AND o.order_purchase_timestamp < TIMESTAMP '2018-01-01'
AND i.n_items > 1
GROUP BY 1 ORDER BY 2 DESC;
